sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {
    function caseByMarker(marker) {
        var c = new GlideRecord('x_snc_sas_positi_0_case');
        c.addQuery('short_description', marker);
        c.orderByDesc('sys_created_on');
        c.setLimit(1);
        c.query();
        return c.next() ? c.getUniqueValue() : '';
    }

    var caseId = caseByMarker('ATF - uneven 60/40 funding split');

    var rowTotal = 0, rowCount = 0;
    var f = new GlideRecord('x_snc_sas_positi_0_funding');
    f.addQuery('parent_case', caseId);
    f.query();
    while (f.next()) {
        rowCount++;
        rowTotal += parseFloat(f.getValue('funding_pct') || '0');
    }

    // Reported, deliberately NOT asserted. GlideAggregate SUM is measured
    // returning the last row's value instead of the total on this column
    // (COUNT is correct, SUM is not). Asserting the defect would turn an
    // eventual platform fix into a test failure, so it is surfaced for a
    // human to read instead.
    var aggTotal = '(none)';
    var agg = new GlideAggregate('x_snc_sas_positi_0_funding');
    agg.addQuery('parent_case', caseId);
    agg.addAggregate('SUM', 'funding_pct');
    agg.query();
    if (agg.next()) { aggTotal = agg.getAggregate('SUM', 'funding_pct'); }
    stepResult.setOutputMessage(
        'row-by-row total=' + rowTotal + ' over ' + rowCount +
        ' rows; GlideAggregate SUM reported=' + aggTotal +
        ' (if these now agree, the platform defect behind the B.2 deviation may be fixed)'
    );

    describe('Funding total for an uneven split', function () {
        it('finds the case the previous step inserted', function () {
            expect(caseId).toBeTruthy();
        });
        it('finds both funding rows', function () {
            expect(rowCount).toBe(2);
        });
        it('totals exactly 100 when summed row by row', function () {
            expect(rowTotal).toBe(100);
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
